-- Existing text and cold trial overrides, captured before enabling all voice scenarios.
CREATE OR REPLACE FUNCTION public.get_training_access(p_user_id uuid, p_training_kind text DEFAULT 'text'::text, p_scenario_title text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE v_company uuid; v_sub public.company_subscriptions%rowtype; v_email text; v_kind text:=lower(coalesce(p_training_kind,'text')); v_title text:=lower(coalesce(p_scenario_title,'')); v_used integer:=0; v_obj_used integer:=0; v_cold_used integer:=0; BEGIN SELECT email INTO v_email FROM auth.users WHERE id=p_user_id; IF lower(coalesce(v_email,''))='expert-26@yandex.ru' THEN RETURN jsonb_build_object('allowed',true,'mode','test','training_kind',v_kind,'unlimited',true,'used',0); END IF; SELECT company_id INTO v_company FROM public.profiles WHERE id=p_user_id; IF v_company IS NULL THEN RETURN jsonb_build_object('allowed',false,'reason','company_not_found'); END IF; SELECT * INTO v_sub FROM public.company_subscriptions WHERE company_id=v_company; IF NOT FOUND THEN RETURN jsonb_build_object('allowed',false,'reason','subscription_not_found'); END IF; IF v_sub.status IN ('active','paid') AND coalesce(v_sub.current_period_end,now())>now() THEN SELECT count(*) INTO v_used FROM public.saletrening_sessions WHERE company_id=v_company AND employee_id=p_user_id AND voice_mode=(v_kind='voice') AND started_at>=date_trunc('day',now()); IF v_used>=3 THEN RETURN jsonb_build_object('allowed',false,'reason','daily_limit','mode','paid','used',v_used,'limit',3,'period_end',v_sub.current_period_end); END IF; RETURN jsonb_build_object('allowed',true,'mode','paid','training_kind',v_kind,'used',v_used,'limit',3,'period_end',v_sub.current_period_end); END IF; IF v_sub.status='trial' THEN IF v_kind='text' THEN RETURN jsonb_build_object('allowed',true,'mode','trial','trial_type','text','temporary_text_unlimited',true); END IF; IF v_title LIKE '%возраж%' OR v_title LIKE '%objection%' THEN v_obj_used:=v_sub.trial_objection_used; IF v_obj_used>=2 THEN RETURN jsonb_build_object('allowed',false,'reason','trial_objection_exhausted','mode','trial','used',v_obj_used,'limit',2); END IF; RETURN jsonb_build_object('allowed',true,'mode','trial','trial_type','objection','used',v_obj_used,'limit',2); END IF; IF v_title LIKE '%холод%' OR v_title LIKE '%cold%' THEN v_cold_used:=v_sub.trial_cold_call_used; RETURN jsonb_build_object('allowed',true,'mode','trial','trial_type','cold_call','used',v_cold_used,'limit',1,'temporary_cold_unlimited',true); END IF; RETURN jsonb_build_object('allowed',false,'reason','trial_training_type_not_free','mode','trial'); END IF; RETURN jsonb_build_object('allowed',false,'reason','subscription_expired','mode','expired','period_end',v_sub.current_period_end,'trial_ends_at',v_sub.trial_ends_at); END; $function$
;
